def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = opp.count('C')

    if opp_c == n:
        return 'C'

    if opp_c * 100 < n * 45:
        return 'D'

    last_me = me[-1]
    last_opp = opp[-1]

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            dd_streak += 1
        else:
            break

    recent_len = min(10, n)
    recent_c = opp[-recent_len:].count('C')

    if last_me == 'C' and last_opp == 'D':
        if n >= 2 and me[-2] == 'D' and opp[-2] == 'D':
            return 'C'
        if recent_c >= 8 and opp_c * 2 > n:
            return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'D':
        if opp_c * 2 > n:
            if dd_streak >= 2:
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    if last_me == 'D' and last_opp == 'C':
        opp_def = n - opp_c
        if opp_def * 2 > n:
            return 'D'
        else:
            return 'C'

    return 'C'
